#!/bin/sh
# envscan.sh - read-only environment scanner for any POSIX sh (dash, bash, ksh, #
# busybox ash, macOS, AIX, Solaris xpg4; z/OS UNIX and IBM i PASE: tier 2, unverified). Generated by tools/build.py; do not edit. #
# Usage: sh envscan.sh [--deep] [--net] [--out DIR] [--only IDS] [--skip IDS] #
#        [--timeout SEC] [--budget SEC] [--no-redact] [--list-probes] [--version] #
# Every preamble line ends with " #": if the file was saved with CRLF line endings #
# the carriage returns land in comments until the script has repaired itself. #
# The preamble avoids $(...) so that a pre-POSIX Bourne /bin/sh can run it. #
if [ -z "${ENVSCAN_REEXEC:-}" ] && [ -f "$0" ]; then #
  es_cr=`printf '\r'` #
  es_l1=`head -n 1 "$0" 2>/dev/null` # not awk or sed: MSYS builds drop the CR #
  case "$es_l1" in #
    *"$es_cr") #
      es_d="${TMPDIR:-/tmp}/envscan-crlf.$$" #
      if (umask 077; mkdir "$es_d") 2>/dev/null && tr -d '\r' <"$0" >"$es_d/envscan.sh"; then #
        ENVSCAN_REEXEC=crlf; ENVSCAN_CRLF_DIR=$es_d; ENVSCAN_SCRIPT=$0 #
        export ENVSCAN_REEXEC ENVSCAN_CRLF_DIR ENVSCAN_SCRIPT #
        trap 'rm -rf "$es_d"' 0 # an exec that fails ends this shell: the copy goes with it (exec drops the trap) #
        for es_sh in /bin/sh /usr/bin/sh /QOpenSys/usr/bin/sh /QOpenSys/pkgs/bin/bash; do #
          if [ -f "$es_sh" ] && [ -x "$es_sh" ]; then exec "$es_sh" "$es_d/envscan.sh" ${1+"$@"}; fi #
        done #
      fi #
      printf '%s\n' "envscan: CRLF line endings and no writable temp directory or no shell to run the repaired copy; convert with: tr -d '\\r'" >&2 #
      exit 2 ;; #
  esac #
fi #
if [ -z "${ENVSCAN_POSIX:-}" ]; then #
  if ( eval 'es_t=$((1 + 1)); es_u=$(printf ab); [ "$es_t" = 2 ] && [ "${es_u#a}" = b ]' ) >/dev/null 2>&1; then :; else #
    for es_sh in /usr/xpg4/bin/sh /bin/ksh /usr/bin/ksh /bin/bash /usr/bin/bash /usr/local/bin/bash /QOpenSys/usr/bin/sh /QOpenSys/pkgs/bin/bash; do #
      if [ -f "$es_sh" ] && [ -x "$es_sh" ]; then #
        ENVSCAN_POSIX=1; export ENVSCAN_POSIX #
        exec "$es_sh" "$0" ${1+"$@"} #
      fi #
    done #
    printf '%s\n' "envscan: this /bin/sh is not POSIX and no POSIX shell was found (xpg4 sh, ksh, bash)" >&2 #
    exit 2 #
  fi #
fi #
ES_PATH_PREPENDED= #
ES_PRE_ZOS=; ES_PRE_CEE_SET=; ES_PRE_CEE=; ES_PRE_CVT_SET=; ES_PRE_CVT= #
case `uname -s 2>/dev/null` in #
  SunOS) if [ -d /usr/xpg4/bin ]; then PATH="/usr/xpg4/bin${PATH:+:$PATH}"; export PATH; ES_PATH_PREPENDED=/usr/xpg4/bin; fi ;; #
  OS/390) # z/OS UNIX: tagged ASCII files are converted on read; APPEND to the user's run-time options #
    ES_PRE_ZOS=1; ES_PRE_CEE_SET=${_CEE_RUNOPTS+x}; ES_PRE_CEE=${_CEE_RUNOPTS-}; ES_PRE_CVT_SET=${_BPXK_AUTOCVT+x}; ES_PRE_CVT=${_BPXK_AUTOCVT-} # kept for env.vars #
    _BPXK_AUTOCVT=ON; export _BPXK_AUTOCVT #
    _CEE_RUNOPTS="${_CEE_RUNOPTS:+$_CEE_RUNOPTS }FILETAG(AUTOCVT,AUTOTAG) POSIX(ON)"; export _CEE_RUNOPTS ;; #
  OS400) # IBM i: PASE (ASCII, AIX-like) only; QSH runs in the job's EBCDIC CCSID #
    PATH="/QOpenSys/usr/bin:/QOpenSys/usr/sbin${PATH:+:$PATH}"; export PATH # od is found even when the caller's PATH lacks it #
    es_asc=`printf A | od -An -tx1 2>/dev/null` #
    case "$es_asc" in #
      *41*) ES_PATH_PREPENDED=/QOpenSys/usr/bin:/QOpenSys/usr/sbin ;; #
      *) #
        if [ -z "${ENVSCAN_QSH:-}" ] && [ -x /QOpenSys/usr/bin/sh ]; then #
          ENVSCAN_QSH=1; export ENVSCAN_QSH #
          exec /QOpenSys/usr/bin/sh "$0" ${1+"$@"} #
        fi #
        printf '%s\n' "envscan: this shell is not ASCII (IBM i QSH?); run envscan.sh from PASE (ssh, or CALL QP2TERM)" >&2 #
        exit 2 ;; #
    esac ;; #
esac #
ES_ORIG_UMASK=`umask` #
umask 077 #
ES_SCRIPT=${ENVSCAN_SCRIPT:-$0} #
# The CRLF copy's directory is removed at exit (es_cleanup), so it is trusted only in the #
# re-exec child, and only when it is the directory of the running script (the copy) and a #
# real envscan-crlf.<pid> directory; ENVSCAN_CRLF_DIR alone never names what rm -rf removes. #
ES_CRLF_DIR= #
ES_REEXEC=${ENVSCAN_REEXEC:-} #
if [ "$ES_REEXEC" = crlf ] && [ -n "${ENVSCAN_CRLF_DIR:-}" ] && [ "${0%/*}" = "$ENVSCAN_CRLF_DIR" ]; then #
  case "${ENVSCAN_CRLF_DIR##*/}" in #
    envscan-crlf.*[!0-9]*) ;; #
    envscan-crlf.[0-9]*) case "$ENVSCAN_CRLF_DIR" in */../*|*/./*) ;; *) [ -d "$ENVSCAN_CRLF_DIR" ] && [ ! -h "$ENVSCAN_CRLF_DIR" ] && ES_CRLF_DIR=$ENVSCAN_CRLF_DIR ;; esac ;; #
  esac #
fi #
unset ENVSCAN_REEXEC ENVSCAN_CRLF_DIR ENVSCAN_SCRIPT ENVSCAN_POSIX ENVSCAN_QSH #
